SDL_Color C(Uint8 r,Uint8 g,Uint8 b,Uint8 a=255){return SDL_Color{r,g,b,a};}
void fill(int x,int y,int w,int h,SDL_Color c){SDL_SetRenderDrawColor(ren,c.r,c.g,c.b,c.a);SDL_Rect r{x,y,w,h};SDL_RenderFillRect(ren,&r);} 
