struct CachedText{SDL_Texture* tex=nullptr;int w=0,h=0;};
static std::unordered_map<std::string,CachedText> textCache;
std::string textKey(const std::string&s,SDL_Color c){return s+"\x1f"+std::to_string(c.r)+","+std::to_string(c.g)+","+std::to_string(c.b)+","+std::to_string(c.a);}
void clearTextCache(){for(auto &kv:textCache)if(kv.second.tex)SDL_DestroyTexture(kv.second.tex);textCache.clear();}
void text(const std::string&s,int x,int y,int size,SDL_Color c,bool center=false){if(!font||s.empty())return;std::string k=textKey(s,c);auto it=textCache.find(k);if(it==textCache.end()){SDL_Surface* sf=TTF_RenderUTF8_Blended(font,s.c_str(),c);if(!sf)return;CachedText ct;ct.w=sf->w;ct.h=sf->h;ct.tex=SDL_CreateTextureFromSurface(ren,sf);SDL_FreeSurface(sf);if(!ct.tex)return;it=textCache.emplace(k,ct).first;}float sc=size/20.0f;int dw=(int)(it->second.w*sc),dh=(int)(it->second.h*sc);int xx=center?x-dw/2:x;SDL_Rect d{xx,y,dw,dh};SDL_RenderCopy(ren,it->second.tex,nullptr,&d);} 
std::vector<std::string> wrap(const std::string&s,int maxChars){std::vector<std::string> out; std::string cur,word; for(size_t i=0;i<=s.size();i++){char ch=i<s.size()?s[i]:' '; if(ch=='\n'){if(!word.empty()){if(!cur.empty())cur+=' ';cur+=word;word.clear();}out.push_back(cur);cur.clear();continue;} if(ch==' '){if(!word.empty()){if((int)(cur.size()+word.size()+1)>maxChars&&!cur.empty()){out.push_back(cur);cur=word;}else{if(!cur.empty())cur+=' ';cur+=word;}word.clear();}}else word+=ch;} if(!cur.empty())out.push_back(cur);return out;}
const StoryRef* story(const char* id){for(int i=0;i<STORY_COUNT;i++)if(!strcmp(STORIES[i].id,id))return &STORIES[i];return nullptr;}
void showStory(const char* id, void(*done)()=nullptr){auto s=story(id);if(!s)return;dlg=s->lines;dlgCount=s->count;dlgIndex=0;dlgDone=done;mode=DIALOGUE;}
void say(const char*sp,const char*t,void(*done)()=nullptr){static Line l; l={sp,t}; dlg=&l;dlgCount=1;dlgIndex=0;dlgDone=done;mode=DIALOGUE;}
void advance(){if(++dlgIndex>=dlgCount){auto cb=dlgDone;dlg=nullptr;mode=WORLD;dlgDone=nullptr;if(cb)cb();}}
void toast(const char*s){toastMsg=s;toastT=3.0f;}
const char* savePath(){return "ux0:data/AindaEmTransito/save.bin";}
void ensureDir(){mkdir("ux0:data",0777);mkdir("ux0:data/AindaEmTransito",0777);} 
void saveGame(){ensureDir();S.room=roomId;S.x=heroX;S.y=heroY;FILE*f=fopen(savePath(),"wb");if(f){fwrite(&S,sizeof(S),1,f);fclose(f);toast("Viagem guardada.");}}
bool loadGame(){FILE*f=fopen(savePath(),"rb");if(!f)return false;SaveData t;bool ok=fread(&t,sizeof(t),1,f)==1&&t.magic==0x41545256;fclose(f);if(ok){S=t;roomId=t.room;heroX=t.x;heroY=t.y;mode=WORLD;}return ok;}
void newGame(){S=SaveData{};roomId=ATELIER;heroX=466;heroY=441;showStory("intro");}
void go(int id,float x,float y){roomId=id;heroX=x;heroY=y;mode=WORLD;saveGame();if(id==HUB&&!S.f.hubVisited){S.f.hubVisited=true;showStory("hubIntro");} if(id==COURTYARD)showStory("courtyardIntro"); if(id==ARCHIVE_R)showStory("archiveIntro");}

