void drawDodge(){fill(0,0,W,H,C(7,8,18));outline(181,88,598,280,C(240,230,220));for(int i=0;i<7;i++){float yy=110+fmodf(timeSec*90+i*61,240.0f);fill(220+i*78,(int)yy,42,14,C(216,126,131));}fill((int)heartX-6,(int)heartY-6,12,12,C(110,210,220));text("DESVIE · segure R para mover com precisao",480,405,16,C(220,210,205),true);}
void drawPhoto(){fill(0,0,W,H,C(18,31,42));text("CABINE DE RETRATOS",480,35,28,C(238,208,171),true);fill(160,110,640,310,C(70,91,96));int cx=480+photoX,cy=320+photoY;drawActor(cx-150,cy,C(255,184,107));drawActor(cx-50,cy,C(241,186,218));drawActor(cx+50,cy,C(180,163,250));drawActor(cx+150,cy,C(130,218,221));outline(220,170,520,210,C(190,225,194));text("Direcional ajusta · X fotografa",480,460,16,C(210,205,190),true);}
void drawEnding(){fill(0,0,W,H,C(8,8,16));text("FELIZ ANIVERSARIO, ANANDA",480,90,38,C(255,224,162),true);text("Ainda tem muita pagina pela frente.",480,175,22,C(239,223,209),true);text("Obrigado por jogar.",480,350,18,C(190,180,205),true);}
void render(){SDL_SetRenderDrawBlendMode(ren,SDL_BLENDMODE_BLEND);switch(mode){case TITLE:drawTitle();break;case WORLD:drawWorld();break;case DIALOGUE:drawDialogue();break;case PIPES:drawPipes();break;case BELLS:drawBells();break;case ARCHIVE:drawArchive();break;case BRIDGE:drawBridge();break;case SORTING:drawSorting();break;case BATTLE:drawBattle();break;case DODGE:drawDodge();break;case PHOTO:drawPhoto();break;case ENDING:drawEnding();break;default:drawWorld();break;}if(toastT>0){fill(240,500,480,32,C(10,10,18,230));text(toastMsg,480,505,14,C(240,226,205),true);}SDL_RenderPresent(ren);}

void handleButton(SDL_GameControllerButton b){if(mode==TITLE){if(b==SDL_CONTROLLER_BUTTON_DPAD_UP)menuSel=(menuSel+2)%3;if(b==SDL_CONTROLLER_BUTTON_DPAD_DOWN)menuSel=(menuSel+1)%3;if(b==SDL_CONTROLLER_BUTTON_A){if(menuSel==0){if(!loadGame())newGame();}else if(menuSel==1)newGame();else running=false;}return;}if(mode==DIALOGUE){if(b==SDL_CONTROLLER_BUTTON_A)advance();return;}if(mode==WORLD){if(b==SDL_CONTROLLER_BUTTON_A){if(auto o=nearest())action(o->action);else toast("Aproxime-se de um objeto marcado.");}if(b==SDL_CONTROLLER_BUTTON_START){saveGame();}return;}if(mode==PIPES){if(b==SDL_CONTROLLER_BUTTON_DPAD_LEFT)pipeCur=(pipeCur+8)%9;if(b==SDL_CONTROLLER_BUTTON_DPAD_RIGHT)pipeCur=(pipeCur+1)%9;if(b==SDL_CONTROLLER_BUTTON_DPAD_UP)pipeCur=(pipeCur+6)%9;if(b==SDL_CONTROLLER_BUTTON_DPAD_DOWN)pipeCur=(pipeCur+3)%9;if(b==SDL_CONTROLLER_BUTTON_A)pipeCells[pipeCur]=rotMask(pipeCells[pipeCur]);if(b==SDL_CONTROLLER_BUTTON_START){if(pipesConnected()){S.f.pipes=true;S.f.para=true;mode=WORLD;showStory("pipesDone",[](){startBattle(1);});}else toast("Ainda ha um trecho desconectado.");}if(b==SDL_CONTROLLER_BUTTON_B)mode=WORLD;return;}if(mode==BELLS){int n=-1;if(b==SDL_CONTROLLER_BUTTON_DPAD_LEFT)n=0;if(b==SDL_CONTROLLER_BUTTON_DPAD_UP)n=1;if(b==SDL_CONTROLLER_BUTTON_DPAD_RIGHT)n=2;if(n>=0){if(n!=bellSeq[bellRound][bellPos]){bellPos=0;toast("Sequencia incorreta. Tente outra vez.");}else{bellPos++;int len=(bellRound==0?3:(bellRound==1?4:5)); if(bellPos>=len){bellRound++;bellPos=0;if(bellRound>=3){S.f.com=true;mode=WORLD;showStory("bellsDone");saveGame();}}}}if(b==SDL_CONTROLLER_BUTTON_B)mode=WORLD;return;}if(mode==ARCHIVE){if(b==SDL_CONTROLLER_BUTTON_DPAD_LEFT)archiveSel=(archiveSel+5)%6;if(b==SDL_CONTROLLER_BUTTON_DPAD_RIGHT)archiveSel=(archiveSel+1)%6;if(b==SDL_CONTROLLER_BUTTON_DPAD_UP)archiveSel=(archiveSel+3)%6;if(b==SDL_CONTROLLER_BUTTON_DPAD_DOWN)archiveSel=(archiveSel+3)%6;if(b==SDL_CONTROLLER_BUTTON_A){if(archiveSel==2){S.f.archiveDone=true;mode=WORLD;showStory("archiveDone");saveGame();}else toast("Essa ficha tem um campo diferente.");}if(b==SDL_CONTROLLER_BUTTON_B)mode=WORLD;return;}if(mode==BRIDGE){if(b==SDL_CONTROLLER_BUTTON_DPAD_LEFT)bridgeMove(-1,0);if(b==SDL_CONTROLLER_BUTTON_DPAD_RIGHT)bridgeMove(1,0);if(b==SDL_CONTROLLER_BUTTON_DPAD_UP)bridgeMove(0,-1);if(b==SDL_CONTROLLER_BUTTON_DPAD_DOWN)bridgeMove(0,1);if(b==SDL_CONTROLLER_BUTTON_B)mode=WORLD;return;}if(mode==SORTING){int v=-1;if(b==SDL_CONTROLLER_BUTTON_DPAD_LEFT)v=0;if(b==SDL_CONTROLLER_BUTTON_DPAD_UP)v=1;if(b==SDL_CONTROLLER_BUTTON_DPAD_RIGHT)v=2;static const int q[9]={0,2,1,2,0,1,1,0,2};if(v>=0){if(v==q[sortIndex]){sortIndex++;if(sortIndex>=9){S.f.sorted=true;mode=WORLD;showStory("sortingDone",[](){startBattle(3);});saveGame();}}else toast("Confira: remetente, destinatario ou confirmacao?");}if(b==SDL_CONTROLLER_BUTTON_B)mode=WORLD;return;}if(mode==BATTLE){if(b==SDL_CONTROLLER_BUTTON_A){battleMercy=std::min(100,battleMercy+25);dodgeT=3.0f;heartX=480;heartY=250;mode=DODGE;}if(b==SDL_CONTROLLER_BUTTON_Y){if(battleMercy>=100){battleDone();mode=WORLD;}else toast("Ainda nao esta pronto para poupar.");}return;}if(mode==PHOTO){if(b==SDL_CONTROLLER_BUTTON_DPAD_LEFT)photoX-=8;if(b==SDL_CONTROLLER_BUTTON_DPAD_RIGHT)photoX+=8;if(b==SDL_CONTROLLER_BUTTON_DPAD_UP)photoY-=8;if(b==SDL_CONTROLLER_BUTTON_DPAD_DOWN)photoY+=8;if(b==SDL_CONTROLLER_BUTTON_A){showStory("finalSetup",[](){showStory("boxBefore",[](){showStory("boxAfter",[](){showStory("ending",[](){S.f.complete=true;saveGame();mode=ENDING;});});});});}if(b==SDL_CONTROLLER_BUTTON_B)mode=WORLD;return;}}

int main(int argc,char**argv){(void)argc;(void)argv;SDL_Init(SDL_INIT_VIDEO|SDL_INIT_GAMECONTROLLER|SDL_INIT_AUDIO);TTF_Init();win=SDL_CreateWindow("Ainda em Transito",SDL_WINDOWPOS_CENTERED,SDL_WINDOWPOS_CENTERED,W,H,0);ren=SDL_CreateRenderer(win,-1,SDL_RENDERER_ACCELERATED|SDL_RENDERER_PRESENTVSYNC);font=TTF_OpenFont("app0:/assets/NanaPixel.ttf",20);if(!font)font=TTF_OpenFont("assets/NanaPixel.ttf",20);initRooms();SDL_GameController*pad=nullptr;for(int i=0;i<SDL_NumJoysticks();i++)if(SDL_IsGameController(i)){pad=SDL_GameControllerOpen(i);break;}Uint32 last=SDL_GetTicks();while(running){Uint32 now=SDL_GetTicks();float dt=std::min(.033f,(now-last)/1000.0f);last=now;timeSec+=dt;if(toastT>0)toastT-=dt;SDL_Event e;while(SDL_PollEvent(&e)){if(e.type==SDL_QUIT)running=false;if(e.type==SDL_CONTROLLERBUTTONDOWN)handleButton((SDL_GameControllerButton)e.cbutton.button);if(e.type==SDL_KEYDOWN){SDL_GameControllerButton b=SDL_CONTROLLER_BUTTON_INVALID;switch(e.key.keysym.sym){case SDLK_RETURN:b=SDL_CONTROLLER_BUTTON_A;break;case SDLK_ESCAPE:b=SDL_CONTROLLER_BUTTON_B;break;case SDLK_LEFT:b=SDL_CONTROLLER_BUTTON_DPAD_LEFT;break;case SDLK_RIGHT:b=SDL_CONTROLLER_BUTTON_DPAD_RIGHT;break;case SDLK_UP:b=SDL_CONTROLLER_BUTTON_DPAD_UP;break;case SDLK_DOWN:b=SDL_CONTROLLER_BUTTON_DPAD_DOWN;break;case SDLK_SPACE:b=SDL_CONTROLLER_BUTTON_Y;break;default:break;}if(b!=SDL_CONTROLLER_BUTTON_INVALID)handleButton(b);}}
 if(mode==WORLD){float dx=0,dy=0;const Uint8*k=SDL_GetKeyboardState(nullptr);if(k[SDL_SCANCODE_LEFT]||k[SDL_SCANCODE_A])dx-=1;if(k[SDL_SCANCODE_RIGHT]||k[SDL_SCANCODE_D])dx+=1;if(k[SDL_SCANCODE_UP]||k[SDL_SCANCODE_W])dy-=1;if(k[SDL_SCANCODE_DOWN]||k[SDL_SCANCODE_S])dy+=1;if(pad){float ax=SDL_GameControllerGetAxis(pad,SDL_CONTROLLER_AXIS_LEFTX)/32767.0f,ay=SDL_GameControllerGetAxis(pad,SDL_CONTROLLER_AXIS_LEFTY)/32767.0f;if(fabs(ax)>.18f)dx=ax;if(fabs(ay)>.18f)dy=ay;}float m=hypotf(dx,dy);if(m>1){dx/=m;dy/=m;}float sp=150;float nx=heroX+dx*sp*dt,ny=heroY+dy*sp*dt;if(!blocked(nx,heroY))heroX=nx;if(!blocked(heroX,ny))heroY=ny;}
 if(mode==DODGE){float dx=0,dy=0;if(pad){dx=SDL_GameControllerGetAxis(pad,SDL_CONTROLLER_AXIS_LEFTX)/32767.0f;dy=SDL_GameControllerGetAxis(pad,SDL_CONTROLLER_AXIS_LEFTY)/32767.0f;}const Uint8*k=SDL_GetKeyboardState(nullptr);if(k[SDL_SCANCODE_LEFT])dx=-1;if(k[SDL_SCANCODE_RIGHT])dx=1;if(k[SDL_SCANCODE_UP])dy=-1;if(k[SDL_SCANCODE_DOWN])dy=1;heartX=std::clamp(heartX+dx*210*dt,190.0f,770.0f);heartY=std::clamp(heartY+dy*210*dt,97.0f,358.0f);dodgeT-=dt;if(dodgeT<=0){mode=BATTLE;if(battleMercy>=100)toast("POUPAR chegou a 100%.");}}
 SDL_SetRenderDrawColor(ren,0,0,0,255);SDL_RenderClear(ren);render();}saveGame();if(pad)SDL_GameControllerClose(pad);clearTextCache();if(font)TTF_CloseFont(font);SDL_DestroyRenderer(ren);SDL_DestroyWindow(win);TTF_Quit();SDL_Quit();return 0;}
